#[test]
fn test_deserialize_empty_header() {
    let content = r#"
        <InternetMessageHeader HeaderName="X-Is-Empty"/>"#;
    let expected = InternetMessageHeader {
        header_name: "X-Is-Empty".to_string(),
        value: None,
    };
    assert_deserialized_content(content, expected);
}
